package cn.sifangguan.hotelaios.finance;

import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceAssetGainModels.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Actual physical identity + original valuation proof + independent review, never an automatic gain on asset registration. */
@Service @Transactional
public class FinanceAssetGainService {
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext db;private final AccessPolicy access;
 private final FinanceAccountingService accounting;private final AuditWriter audit;
 public FinanceAssetGainService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext db,AccessPolicy access,FinanceAccountingService accounting,AuditWriter audit){this.jdbc=jdbc;this.db=db;this.access=access;this.accounting=accounting;this.audit=audit;}
 private TenantPrincipal read(){access.requireAnyPermission("finance.read","finance.accounting.read");var p=access.principal();db.apply(p.tenantId());return p;}
 private TenantPrincipal write(){var p=read();access.requirePermission("finance.accounting.write");return p;}
 private Map<String,Object> one(String sql,MapSqlParameterSource b){var rows=jdbc.queryForList(sql,b);if(rows.size()!=1)throw missing();return rows.getFirst();}
 private LocalDate date(Object value){return LocalDate.parse(value.toString().substring(0,10));}
 private LocalDate today(TenantPrincipal p){return jdbc.queryForObject("select (clock_timestamp() at time zone timezone)::date from tenant where id=:tenant",base(p),LocalDate.class);}
 private Map<String,Object> gain(TenantPrincipal p,UUID id,boolean lock){var r=one("select * from fs_asset_gain where tenant_id=:tenant and id=:id"+(lock?" for update":""),base(p).addValue("id",id));access.requireOrgScope(id(r.get("hotel_id")));return r;}
 private Map<String,Object> physical(TenantPrincipal p,UUID asset,UUID hotel){var row=one("select * from store_fixed_asset where tenant_id=:tenant and id=:asset and hotel_org_unit_id=:hotel for update",base(p).addValue("asset",asset).addValue("hotel",hotel));if(Set.of("RETIRED","MISSING").contains(row.get("status")))throw conflict("原实物已报废或缺失，不可作为已发现盘盈资产");return row;}
 private void uncapitalized(TenantPrincipal p,UUID asset){var b=base(p).addValue("asset",asset).addValue("assetText",asset.toString());
  if(jdbc.queryForObject("select exists(select 1 from fs_asset_card where tenant_id=:tenant and physical_asset_id=:asset) or exists(select 1 from fm_subledger where tenant_id=:tenant and kind='ASSET' and status='ACTIVE' and physical_asset_id=:asset) or exists(select 1 from fo_document where tenant_id=:tenant and details->>'physicalAssetId'=:assetText and status not in ('REJECTED','CANCELLED') and (type='ASSET' or details->>'treatment'='ASSET'))",b,Boolean.class))throw conflict("该实物已有财务卡、实际资本来源或已核对期初，不能再认盘盈重复资本化");
 }
 private Map<String,Object> book(TenantPrincipal p,UUID id){var k=one("select * from fa_book where tenant_id=:tenant and id=:book",base(p).addValue("book",id));access.requireOrgScope(id(k.get("hotel_id")));var config=one("select * from finance_store_config where tenant_id=:tenant and hotel_id=:hotel and enabled",base(p).addValue("hotel",k.get("hotel_id")));if(!Objects.equals(k.get("company_id"),config.get("company_id")))throw conflict("原账套法人和当前组织财务映射不一致，须先核对实际主体");return k;}
 private void account(TenantPrincipal p,UUID book,String code,Set<String> categories){var a=one("select category from fa_account where tenant_id=:tenant and book_id=:book and code=:code and enabled",base(p).addValue("book",book).addValue("code",code));if(!categories.contains(a.get("category")))throw conflict("盘盈政策所选真实科目性质不适用，请独立财务核对，不自动猜测损益或税务处理");}
 public Map<String,Object> context(UUID hotel){var p=read();access.requireOrgScope(hotel);var b=base(p).addValue("hotel",hotel);return output(Map.of(
  "books",jdbc.queryForList("select id,name,company_id from fa_book where tenant_id=:tenant and hotel_id=:hotel order by name",b),
  "assets",jdbc.queryForList("select a.id,a.asset_code,a.name,a.row_version from store_fixed_asset a where a.tenant_id=:tenant and a.hotel_org_unit_id=:hotel and a.status not in ('RETIRED','MISSING') and not exists(select 1 from fs_asset_card c where c.tenant_id=a.tenant_id and c.physical_asset_id=a.id) and not exists(select 1 from fs_asset_gain g where g.tenant_id=a.tenant_id and g.physical_asset_id=a.id and g.status not in ('REJECTED','CANCELLED')) order by a.asset_code",b),
  "departments",FinanceCostDimensions.departments(jdbc,p.tenantId(),hotel),"categories",FinanceCostDimensions.categories(jdbc,p.tenantId(),hotel),
  "accounts",jdbc.queryForList("select a.book_id,a.code,a.name,a.category from fa_account a join fa_book b on b.tenant_id=a.tenant_id and b.id=a.book_id where a.tenant_id=:tenant and b.hotel_id=:hotel and a.enabled order by a.book_id,a.code",b),
  "notice","原实物登记不自动认盘盈。须上传真实估值/盘点依据并由配置独立财务核对，系统不代替估值专家或自动确认合规；审核、会计过账和财务建卡是三个独立状态。"));}
 public Map<String,Object> list(UUID hotel){var p=read();access.requireOrgScope(hotel);return output(Map.of("items",jdbc.queryForList("select g.*,a.name physical_name,v.status voucher_status,e.voucher_id from fs_asset_gain g join store_fixed_asset a on a.tenant_id=g.tenant_id and a.id=g.physical_asset_id left join fa_source_event e on e.tenant_id=g.tenant_id and e.id=g.source_event_id left join fa_voucher v on v.tenant_id=e.tenant_id and v.id=e.voucher_id where g.tenant_id=:tenant and g.hotel_id=:hotel order by g.created_at desc,g.id",base(p).addValue("hotel",hotel))));}
 public Map<String,Object> detail(UUID id){var p=read();var row=gain(p,id,false);var result=new LinkedHashMap<>(row);result.put("originals",jdbc.queryForList("select id,original_name,media_type,size_bytes,sha256,scan_status,created_at from fs_asset_gain_original where tenant_id=:tenant and gain_id=:id order by created_at,id",base(p).addValue("id",id)));result.put("source",jdbc.queryForList("select e.id,e.status,e.voucher_id,v.status voucher_status,v.reversed_by_id from fa_source_event e left join fa_voucher v on v.tenant_id=e.tenant_id and v.id=e.voucher_id where e.tenant_id=:tenant and e.id=:event",base(p).addValue("event",row.get("source_event_id"))));result.put("cards",jdbc.queryForList("select id,asset_code,status from fs_asset_card where tenant_id=:tenant and gain_id=:id",base(p).addValue("id",id)));return output(result);}
 public Map<String,Object> create(Draft in){var p=write();var k=book(p,in.bookId());UUID hotel=id(k.get("hotel_id"));physical(p,in.physicalAssetId(),hotel);var b=base(p).addValue("id",in.requestId());String hash=FinanceService.hash(json(in));var prior=jdbc.queryForList("select * from fs_asset_gain where tenant_id=:tenant and id=:id",b);if(!prior.isEmpty()){if(!hash.equals(prior.getFirst().get("request_hash"))||!p.actorId().equals(prior.getFirst().get("applicant_id")))throw conflict("盘盈申请编号已用于不同原始内容");return detail(in.requestId());}
  uncapitalized(p,in.physicalAssetId());if(jdbc.queryForObject("select count(*) from fs_asset_gain where tenant_id=:tenant and physical_asset_id=:physical and status not in ('REJECTED','CANCELLED')",base(p).addValue("physical",in.physicalAssetId()),Long.class)>0)throw conflict("同一原实物已有未作废盘盈申请，不重复占用或重复资本化");if(in.occurredOn().isAfter(today(p))||in.accountingOn().isAfter(today(p))||in.accountingOn().isBefore(in.occurredOn())||in.accountingOn().isBefore(date(k.get("start_month")))||in.value().signum()<=0||in.value().scale()>2)throw conflict("盘盈真实发生日、开放记账日或价值无效，不倒写迁移前或未来期");
  var category=FinanceCostDimensions.validate(jdbc,p.tenantId(),hotel,in.financialCategoryCode(),in.departmentId(),Set.of("ASSET"));account(p,in.bookId(),in.assetAccount(),Set.of("ASSET"));account(p,in.bookId(),in.creditAccount(),Set.of("EQUITY","REVENUE"));
  var cfg=one("select finance_account_id,director_account_id from finance_store_config where tenant_id=:tenant and hotel_id=:hotel and enabled",base(p).addValue("hotel",hotel));UUID reviewer=id(cfg.get("finance_account_id"));if(reviewer==null||reviewer.equals(p.actorId()))reviewer=id(cfg.get("director_account_id"));if(reviewer==null||reviewer.equals(p.actorId())||jdbc.queryForObject("select count(*) from user_account where tenant_id=:tenant and id=:reviewer and status='ACTIVE'",base(p).addValue("reviewer",reviewer),Long.class)!=1)throw conflict("请配置独立于原制单人的有效财务/财务总监复核人");var asset=physical(p,in.physicalAssetId(),hotel);
  jdbc.update("insert into fs_asset_gain(id,tenant_id,hotel_id,company_id,book_id,physical_asset_id,department_id,financial_category_code,occurred_on,accounting_on,value,asset_account,credit_account,valuation_basis,policy_reference,applicant_id,reviewer_id,request_hash,physical_snapshot,category_snapshot) values(:id,:tenant,:hotel,:company,:book,:physical,:department,:category,:occurred,:accounting,:value,:debit,:credit,:basis,:policy,:actor,:reviewer,:hash,cast(:physicalSnapshot as jsonb),cast(:categorySnapshot as jsonb))",b.addValue("hotel",hotel).addValue("company",k.get("company_id")).addValue("book",in.bookId()).addValue("physical",in.physicalAssetId()).addValue("department",in.departmentId()).addValue("category",in.financialCategoryCode()).addValue("occurred",in.occurredOn()).addValue("accounting",in.accountingOn()).addValue("value",in.value()).addValue("debit",in.assetAccount()).addValue("credit",in.creditAccount()).addValue("basis",in.valuationBasis()).addValue("policy",in.policyReference()).addValue("reviewer",reviewer).addValue("hash",hash).addValue("physicalSnapshot",json(output(asset))).addValue("categorySnapshot",json(output(category))));audit.record("FINANCE_ASSET_GAIN_DRAFT","FS_ASSET_GAIN",in.requestId(),json(in));return detail(in.requestId());
 }
 public void authorizeOriginal(UUID id){var p=write();var row=gain(p,id,true);if(!p.actorId().equals(row.get("applicant_id"))||!row.get("status").equals("DRAFT"))throw conflict("只有原制单人在提交前可以归档估值原件，已提交原件不可改写");}
 public Map<String,Object> registerOriginal(UUID id,UUID attachment,String name,String type,long size,String sha,String objectKey,String scan){authorizeOriginal(id);var p=access.principal();var b=base(p).addValue("id",id).addValue("attachment",attachment);var prior=jdbc.queryForList("select * from fs_asset_gain_original where tenant_id=:tenant and id=:attachment",b);if(!prior.isEmpty()){if(!Objects.equals(prior.getFirst().get("gain_id"),id)||!sha.equals(prior.getFirst().get("sha256")))throw conflict("估值原件编号已绑定不同原始文件");return detail(id);}if(!Set.of("CLEAN","BYPASSED_DEVELOPMENT").contains(scan)||!sha.matches("[a-f0-9]{64}"))throw conflict("必须使用真实通过扫描的不可变原件");jdbc.update("insert into fs_asset_gain_original(id,tenant_id,gain_id,original_name,media_type,size_bytes,sha256,object_key,scan_status,uploaded_by) values(:attachment,:tenant,:id,:name,:type,:size,:sha,:object,:scan,:actor)",b.addValue("name",name).addValue("type",type).addValue("size",size).addValue("sha",sha).addValue("object",objectKey).addValue("scan",scan));jdbc.update("update fs_asset_gain set version=version+1 where tenant_id=:tenant and id=:id",b);audit.record("FINANCE_ASSET_GAIN_ORIGINAL_ARCHIVED","FS_ASSET_GAIN",id,json(Map.of("attachmentId",attachment,"sha256",sha)));return detail(id);}
 public Map<String,Object> original(UUID gain,UUID attachment){var p=read();gain(p,gain,false);audit.record("FINANCE_ASSET_GAIN_ORIGINAL_READ","FS_ASSET_GAIN",gain,json(Map.of("attachmentId",attachment)));return one("select * from fs_asset_gain_original where tenant_id=:tenant and gain_id=:id and id=:attachment",base(p).addValue("id",gain).addValue("attachment",attachment));}
 private List<Map<String,Object>> proof(TenantPrincipal p,UUID gain){return jdbc.queryForList("select id,sha256,scan_status,size_bytes from fs_asset_gain_original where tenant_id=:tenant and gain_id=:id order by id",base(p).addValue("id",gain));}
 public Map<String,Object> submit(UUID id,Command in){var p=write();var row=gain(p,id,true);if(!p.actorId().equals(row.get("applicant_id")))throw conflict("只有原制单人可提交盘盈估值");if(row.get("status").equals("PENDING"))return detail(id);version(row,in.expectedVersion());if(!row.get("status").equals("DRAFT"))throw conflict("该盘盈不再为可提交草稿");var original=proof(p,id);if(original.isEmpty())throw conflict("须先上传真实估值/盘点依据原件，不接受只填来源文字");unchangedPhysical(p,row);jdbc.update("update fs_asset_gain set status='PENDING',version=version+1,evidence_snapshot=cast(:evidence as jsonb),submitted_at=now() where tenant_id=:tenant and id=:id",base(p).addValue("id",id).addValue("evidence",json(output(Map.of("items",original)).get("items"))));audit.record("FINANCE_ASSET_GAIN_SUBMITTED","FS_ASSET_GAIN",id,json(in));return detail(id);}
 private void unchangedPhysical(TenantPrincipal p,Map<String,Object> row){var physical=physical(p,id(row.get("physical_asset_id")),id(row.get("hotel_id")));if(!FinanceArchiveSources.canonicalHash(output(physical)).equals(FinanceArchiveSources.canonicalHash(map(row.get("physical_snapshot")))))throw conflict("原实物快照已变化，须取消旧申请重新核实，不把调拨或更名后对象静默认盘盈");uncapitalized(p,id(row.get("physical_asset_id")));book(p,id(row.get("book_id")));}
 public Map<String,Object> review(UUID id,Review in){var p=write();access.requirePermission("finance.review");var row=gain(p,id,true);if(p.actorId().equals(row.get("applicant_id"))||!p.actorId().equals(row.get("reviewer_id")))throw conflict("仅冻结配置的独立财务可复核，不得原制单人自审");if(!row.get("status").equals("PENDING")){if(in.requestId().equals(row.get("review_request_id"))&&FinanceService.hash(json(in)).equals(row.get("review_hash")))return detail(id);throw conflict("原盘盈已经处理，不能重复确认或覆盖独立意见");}version(row,in.expectedVersion());UUID event=null;
  if(in.approved()){unchangedPhysical(p,row);var current=output(Map.of("items",proof(p,id))).get("items");if(!FinanceArchiveSources.canonicalHash(current).equals(FinanceArchiveSources.canonicalHash(rows(row.get("evidence_snapshot")))))throw conflict("估值原件指纹与提交快照不一致，不接受篡改原件");account(p,id(row.get("book_id")),row.get("asset_account").toString(),Set.of("ASSET"));account(p,id(row.get("book_id")),row.get("credit_account").toString(),Set.of("EQUITY","REVENUE"));
   UUID voucher=in.requestId();BigDecimal value=amount(row.get("value"));var actualVoucher=accounting.createVoucherFromSource(new FinanceAccountingModels.Voucher(voucher,id(row.get("book_id")),date(row.get("occurred_on")),date(row.get("accounting_on")),"独立核实实物盘盈："+id,List.of(new FinanceAccountingModels.Line(row.get("asset_account").toString(),value,BigDecimal.ZERO,"实际盘盈估值，不是采购付款",null),new FinanceAccountingModels.Line(row.get("credit_account").toString(),BigDecimal.ZERO,value,"独立确认会计政策，不代表现金收入",null))),"FS_ASSET_GAIN",id,Map.of("companyId",row.get("company_id").toString()));
   event=UUID.nameUUIDFromBytes((id+":asset-gain-source").getBytes(StandardCharsets.UTF_8));var metadata=Map.of("businessTable","fs_asset_gain","businessId",id.toString(),"companyId",row.get("company_id").toString(),"physicalAssetId",row.get("physical_asset_id").toString(),"departmentId",row.get("department_id").toString(),"financialCategoryCode",row.get("financial_category_code").toString(),"ruleEventKey","ACCEPTED","valuationSnapshotHash",row.get("request_hash").toString());
   jdbc.update("insert into fa_source_event(id,tenant_id,hotel_id,company_id,book_id,source_type,source_id,event_key,business_date,accounting_date,amount,summary,metadata,request_hash,status,voucher_id"+(new FinanceAuxiliaryDimensions(jdbc).installed()?",auxiliary_snapshot":"")+") values(:event,:tenant,:hotel,:company,:book,'FS_ASSET_GAIN',:id,'ACCEPTED',:business,:day,:value,'真实实物盘盈独立估值确认',cast(:metadata as jsonb),:hash,'DRAFT',:voucher"+(new FinanceAuxiliaryDimensions(jdbc).installed()?",cast(:auxiliary as jsonb)":"")+")",base(p).addValue("event",event).addValue("hotel",row.get("hotel_id")).addValue("company",row.get("company_id")).addValue("book",row.get("book_id")).addValue("id",id).addValue("business",row.get("occurred_on")).addValue("day",row.get("accounting_on")).addValue("value",value).addValue("metadata",json(metadata)).addValue("hash",FinanceService.hash(json(output(row)))).addValue("voucher",voucher).addValue("auxiliary",json(map(actualVoucher.get("sourceAuxiliarySnapshot")))));jdbc.update("update fa_voucher set kind='SOURCE' where tenant_id=:tenant and id=:id",base(p).addValue("id",voucher));
  }
  jdbc.update("update fs_asset_gain set status=:status,version=version+1,review_note=:note,reviewed_by=:actor,reviewed_at=now(),source_event_id=:event,review_request_id=:request,review_hash=:hash where tenant_id=:tenant and id=:id",base(p).addValue("status",in.approved()?"APPROVED":"REJECTED").addValue("note",in.note()).addValue("event",event).addValue("id",id).addValue("request",in.requestId()).addValue("hash",FinanceService.hash(json(in))));audit.record("FINANCE_ASSET_GAIN_REVIEWED","FS_ASSET_GAIN",id,json(in));return detail(id);
 }
 public Map<String,Object> cancel(UUID id,Command in){var p=write();var row=gain(p,id,true);if(!p.actorId().equals(row.get("applicant_id"))||!Set.of("DRAFT","PENDING").contains(row.get("status")))throw conflict("只有原制单人可撤回未确认盘盈，已确认不能删除历史");version(row,in.expectedVersion());jdbc.update("update fs_asset_gain set status='CANCELLED',review_note=:note,version=version+1 where tenant_id=:tenant and id=:id",base(p).addValue("id",id).addValue("note",in.note()));audit.record("FINANCE_ASSET_GAIN_CANCELLED","FS_ASSET_GAIN",id,json(in));return detail(id);}
 public Map<String,Object> card(UUID gainId,Card in){var p=write();var row=gain(p,gainId,true);var b=base(p).addValue("gain",gainId).addValue("id",in.requestId());var existing=jdbc.queryForList("select * from fs_asset_card where tenant_id=:tenant and gain_id=:gain",b);if(!existing.isEmpty()){var prior=existing.getFirst();if(!in.requestId().equals(prior.get("id")))throw conflict("原盘盈已经真实建卡，不得重复");if(!in.assetCode().equals(prior.get("asset_code"))||in.residualValue().compareTo(amount(prior.get("residual_value")))!=0||in.usefulMonths()!=((Number)prior.get("useful_months")).intValue()||!in.inServiceDate().equals(date(prior.get("in_service_date")))||!in.cipAccount().equals(prior.get("cip_account"))||!in.depreciationAccount().equals(prior.get("depreciation_account"))||!in.expenseAccount().equals(prior.get("expense_account")))throw conflict("建卡请求编号已绑定不同冻结内容");return output(existing.getFirst());}
  if(!row.get("status").equals("APPROVED"))throw conflict("盘盈估值须先独立审核通过并实际过账");unchangedPhysical(p,row);var source=one("select e.*,v.status voucher_status,v.reversed_by_id from fa_source_event e join fa_voucher v on v.tenant_id=e.tenant_id and v.id=e.voucher_id where e.tenant_id=:tenant and e.id=:event and e.source_type='FS_ASSET_GAIN' and e.source_id=:gain and e.event_key='ACCEPTED'",b.addValue("event",row.get("source_event_id")));if(!source.get("status").equals("POSTED")||!source.get("voucher_status").equals("POSTED")||source.get("reversed_by_id")!=null||amount(source.get("amount")).compareTo(amount(row.get("value")))!=0)throw conflict("实际盘盈来源尚未独立过账或已红冲，不能承接卡片");
  var actual=jdbc.queryForMap("select coalesce(sum(case when a.code=:debit then l.debit-l.credit else 0 end),0) asset,coalesce(sum(case when a.code=:credit then l.credit-l.debit else 0 end),0) counterpart from fa_voucher_line l join fa_account a on a.tenant_id=l.tenant_id and a.id=l.account_id where l.tenant_id=:tenant and l.voucher_id=:voucher",b.addValue("voucher",source.get("voucher_id")).addValue("debit",row.get("asset_account")).addValue("credit",row.get("credit_account")));if(amount(actual.get("asset")).compareTo(amount(row.get("value")))!=0||amount(actual.get("counterpart")).compareTo(amount(row.get("value")))!=0)throw conflict("实际已过账科目或价值与独立估值快照不一致，不按伪造来源建卡");
  if(in.inServiceDate().isAfter(today(p))||in.inServiceDate().isBefore(date(row.get("occurred_on")))||in.residualValue().compareTo(amount(row.get("value")))>0||in.usefulMonths()<1||in.usefulMonths()>1200)throw conflict("实际投用日期、寿命或残值不合适，请按独立确认政策核对");account(p,id(row.get("book_id")),in.cipAccount(),Set.of("ASSET"));account(p,id(row.get("book_id")),in.depreciationAccount(),Set.of("ASSET"));account(p,id(row.get("book_id")),in.expenseAccount(),Set.of("EXPENSE"));
  jdbc.update("insert into fs_asset_card(id,tenant_id,hotel_id,company_id,physical_asset_id,gain_id,book_id,asset_code,status,original_value,residual_value,useful_months,in_service_date,asset_account,cip_account,depreciation_account,expense_account,created_by) values(:id,:tenant,:hotel,:company,:physical,:gain,:book,:code,'ACTIVE',:value,:residual,:months,:service,:asset,:cip,:depreciation,:expense,:actor)",b.addValue("hotel",row.get("hotel_id")).addValue("company",row.get("company_id")).addValue("physical",row.get("physical_asset_id")).addValue("book",row.get("book_id")).addValue("code",in.assetCode()).addValue("value",row.get("value")).addValue("residual",in.residualValue()).addValue("months",in.usefulMonths()).addValue("service",in.inServiceDate()).addValue("asset",row.get("asset_account")).addValue("cip",in.cipAccount()).addValue("depreciation",in.depreciationAccount()).addValue("expense",in.expenseAccount()));audit.record("FINANCE_ASSET_GAIN_CARD_LINKED","FS_ASSET_GAIN",gainId,json(in));return output(one("select * from fs_asset_card where tenant_id=:tenant and id=:id",b));
 }
}
